import { useState, useEffect } from 'react';
import API from '../../api/axios';
import toast from 'react-hot-toast';

export default function AdminCardRegister() {
  const [rfidUid, setRfidUid] = useState('');
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState('');
  const [loading, setLoading] = useState(false);

  const companyId = "507f1f77bcf86cd799439011"; // Active company ID

  useEffect(() => {
    API.get(`/users/company/${companyId}`)
      .then(res => setUsers(res.data))
      .catch(() => toast.error('Failed to load customer list'));
  }, [companyId]);

  const handleLinkCard = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const { data } = await API.post('/cards/register', {
        cardUID: rfidUid,
        companyId,
        userId: selectedUser
      });
      toast.success(data.message);
      setRfidUid('');
      setSelectedUser('');
    } catch (error) {
      toast.error(error.response?.data?.message || 'Card linking failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full max-w-md p-8 bg-white rounded-2xl shadow-lg border border-gray-100 space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-gray-900">Link RFID Card</h2>
        <p className="text-sm text-gray-500">Assign a physical card tag to a registered customer account.</p>
      </div>

      <form onSubmit={handleLinkCard} className="space-y-4">
        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Card UID (from ESP32)</label>
          <input
            type="text"
            value={rfidUid}
            onChange={(e) => setRfidUid(e.target.value)}
            required
            placeholder="e.g. 4FFE207B"
            className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-indigo-500 font-mono uppercase"
          />
        </div>

        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Select Customer</label>
          <select
            value={selectedUser}
            onChange={(e) => setSelectedUser(e.target.value)}
            required
            className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-indigo-500"
          >
            <option value="">-- Choose Customer --</option>
            {users.map((u) => (
              <option key={u._id} value={u._id}>{u.fullName} ({u.email})</option>
            ))}
          </select>
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-lg transition duration-200 disabled:opacity-50 shadow-sm"
        >
          {loading ? 'Linking...' : 'Save Card Link'}
        </button>
      </form>
    </div>
  );
}
